/* @component: accordion-container */
(function () {
  if (window.__accordionInit) return;
  window.__accordionInit = true;
  document.addEventListener('click', function (e) {
    const header = e.target.closest('.accordion-header');
    if (!header) return;
    const item = header.parentElement;
    if (!item || !item.classList.contains('accordion')) return;
    const isActive = item.classList.contains('_is-active');
    const parent = item.parentElement;
    if (!parent) return;
    function closeNested(el) {
      if (!el) return;
      el.querySelectorAll('.accordion._is-active').forEach(function (nested) {
        nested.classList.remove('_is-active');
        closeNested(nested.querySelector('.accordion-content'));
      });
    }
    document.querySelectorAll('.accordion-container').forEach(function (container) {
      if (!container.contains(item) && !item.contains(container)) {
        container.querySelectorAll('.accordion._is-active').forEach(function (nested) {
          nested.classList.remove('_is-active');
        });
      }
    });
    Array.from(parent.children).forEach(function (sibling) {
      if (sibling !== item && sibling.classList.contains('accordion')) {
        sibling.classList.remove('_is-active');
        closeNested(sibling.querySelector('.accordion-content'));
      }
    });
    if (isActive) {
      item.classList.remove('_is-active');
      closeNested(item.querySelector('.accordion-content'));
    } else {
      item.classList.add('_is-active');
    }
  });
})();
/* @end: accordion-container */
